action.code:
// Early-exit: if the bounding boxes do not overlap, the polygons cannot intersect
if (!P1.boundingBox().intersects(P2.boundingBox()))
    return false;

// Check edge–edge intersections
for (const Segment2d& e1 : P1.edgeSegments()) {
    for (const Segment2d& e2 : P2.edgeSegments()) {
        if (cg3::checkSegmentIntersection2(e1, e2, true))
            return true;
    }
}

// Check if one polygon is entirely inside the other
// (point-in-polygon test for a single vertex is sufficient)
if (P2.contains(P1[0]) || P1.contains(P2[0]))
    return true;

return false;

